 where
     F: FnMut(&'a ast::Expr) -> Result<WalkControl>,
 {
+    if matches!(
+        expr,
+        ast::Expr::Column { .. }
+            | ast::Expr::RowId { .. }
+            | ast::Expr::Literal(_)
+            | ast::Expr::Variable(_)
+    ) {
